SELECT (EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000000' AND name='question_practice_continuous' AND cardinality(statements)=1 AND md5(statements[1])='5812dd9d82c6474144ed67d24d83da65') AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261111010000' AND name='question_practice_option_order' AND cardinality(statements)=1 AND md5(statements[1])='8e115580c1dc373968f8a465c4537429')) AS prerequisites_match,coalesce((SELECT md5(prosrc)='6ad432419c04b73b763410f80231fc72' FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_issue_next(uuid)')),false) AS issue_next_body_matches,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261115000000')) AS repeat_absent;
